var ck = cookie.getCookie('https://book.washai.net/user/read_history.html') || '';
var match = ck.match(/novel_browser_token=([^;]+)/);
var ck_token = match ? match[1] : ""; 

var username = "";
var authMatch = ck.match(/Authorization=([^;]+)/) || ck.match(/FrontRefreshToken=([^;]+)/);
if (authMatch) {
    var parts = authMatch[1].split('.');
    if (parts.length === 3) {
        try {
            var b64 = parts[1].replace(/-/g, '+').replace(/_/g, '/');
            while (b64.length % 4 !== 0) { b64 += '='; }
            var payload = JSON.parse(base64Decode(b64));
            username = payload.username || "";
        } catch(e) {}
    }
}
if (username === "") { username = "解析失败"; }

var my_headers = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/142.0.0.0 Safari/537.36",
    "Accept": "application/json, text/javascript, */*; q=0.01",
    "X-Browser-Token": ck_token,
    "X-Requested-With": "XMLHttpRequest",
    "Referer": "https://book.washai.net/",
    "Origin": "https://book.washai.net"
};
var obj = { "headers": my_headers };

// ==========================================
// 1. 数据收集区
// ==========================================
// 排行榜
var phArr = [];
var phurl = `${fx_Url}/book/book_ranking.html`;
try {
    var phhtml = java.ajax(phurl);
    var phdoc = org.jsoup.Jsoup.parse(phhtml);
    var rankNodes = phdoc.select("#rankType li a");
    if (rankNodes && rankNodes.size() > 0) {
        for (var i = 0; i < rankNodes.size(); i++) {
            var node = rankNodes.get(i);
            var apiUrl = `${fx_Url}/book/listRank?type=${node.attr("data-rank-type")}&limit=30`;
            push(phArr, node.text(), ImRequest(apiUrl, obj), 0.3); 
        }
    }
} catch(e) {}

// 分类 (组装成带大标题的数据结构)
var flArr = [];
var workDirection = [["全部", ""], ["男频", "0"], ["女频", "1"]];
var allCats = [["全部", ""], ["玄幻奇幻", "1"], ["武侠仙侠", "2"], ["都市言情", "3"], ["历史军事", "4"], ["科幻灵异", "5"], ["网游竞技", "6"], ["女生频道", "7"], ["次元同人", "8"]];
var maleCats = [["全部", ""], ["玄幻奇幻", "1"], ["武侠仙侠", "2"], ["都市言情", "3"], ["历史军事", "4"], ["科幻灵异", "5"], ["网游竞技", "6"], ["次元同人", "8"]];
var femaleCats = [["全部", ""], ["女生频道", "7"]];

for (var i = 0; i < workDirection.length; i++) {
    var dName = workDirection[i][0];
    var dVal  = workDirection[i][1];
    var currentCats = allCats;
    if (dName === "男频") currentCats = maleCats;
    if (dName === "女频") currentCats = femaleCats;

    flArr.push({ isHeader: true, title: "= " + dName + " =", url: "", style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 } });

    for (var j = 0; j < currentCats.length; j++) {
        var cName = currentCats[j][0];
        var cVal  = currentCats[j][1];
        var dirParam = (dVal === "") ? "" : "&workDirection=" + dVal;
        var catParam = (cVal === "") ? "" : "&catId=" + cVal;
        var url = `${fx_Url}/book/searchByPage?curr={{page}}&limit=30&keyword=${dirParam}${catParam}`;
        push(flArr, cName, ImRequest(url, obj), 0.3);
    }
}

// 书架
var myArr = [];
var isLogin = (ck_token !== "");
myArr.push({ 
    title: isLogin ? `🔵 已登录：${username}` : "🔴 账户状态：未登录", 
    url: "", type: "text", style: { layout_flexBasisPercent: 1 }
});

if (isLogin) {
    myArr.push({ 
        title: "🚪 退出登录", url: "", type: "button", 
        action: "try{cookie.removeCookie('https://book.washai.net');}catch(e){}; java.toast('✅ 账户已彻底退出'); java.refreshExplore();", 
        style: { layout_flexBasisPercent: 0.46 } 
    });
} else {
    myArr.push({ 
        title: "🔑 立即登录", url: "", type: "button", 
        action: "java.startBrowserAwait('https://book.washai.net/user/login.html', '请登录后返回'); java.refreshExplore();", 
        style: { layout_flexBasisPercent: 0.46 } 
    });
}
var sjurl = `${fx_Url}/user/listBookShelfByPage?curr={{page}}&limit=10&sortBy=updatetime&order=desc/read_history.html`;
push(myArr, "书架", ImRequest(sjurl, obj), 0.46);
myArr.push({ 
    title: "🍪 查看Cookie", url: "", type: "button", 
    action: "var ck = cookie.getCookie('https://book.washai.net/user/read_history.html') || '未获取到Cookie'; java.longToast('当前书架Cookie:\\n' + ck);", 
    style: { layout_flexBasisPercent: 0.46 } 
});
myArr.push({ 
    title: "ℹ️ 关于", url: "", type: "button", 
    action: "var comment = source.bookSourceComment;java.longToast(comment);", 
    style: { layout_flexBasisPercent: 0.46 } 
});


// ==========================================
// 3. 组装渲染 (各管各的，互不干涉)
// ==========================================

// ① 我的模块 (两列排版，单独补全)
ui.push({ 
    title: isMyExpanded ? "▼ 👤 我的 (点击收起)" : "▶ 👤 我的 (点击展开)", 
    url: "", type: "button", 
    action: "(function(){var c={};try{c=JSON.parse(source.getVariable())}catch(e){};c.myExpanded=(c.myExpanded===false?true:false);source.setVariable(JSON.stringify(c));})();java.refreshExplore()", 
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 } 
});
if (isMyExpanded) {
    myArr.forEach(function(item) { ui.push(item); });
    if (myArr.length % 2 !== 1) {
        ui.push({ title: "　", url: "", style: { layout_flexBasisPercent: 0.19} });
    }
}

// ② 排行榜模块 (三列排版，单独补全)
ui.push({ 
    title: isPhExpanded ? "▼ 🔥 排行榜 (点击收起)" : "▶ 🔥 排行榜 (点击展开)", 
    url: "", type: "button", 
    action: "(function(){var c={};try{c=JSON.parse(source.getVariable())}catch(e){};c.phExpanded=(c.phExpanded===false?true:false);source.setVariable(JSON.stringify(c));})();java.refreshExplore()", 
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 } 
});
if (isPhExpanded) {
    phArr.forEach(function(item) {
        ui.push({ title: item.title, url: item.url, type: item.type, action: item.action, style: { layout_flexBasisPercent: 0.3 } });
    });
    if (phArr.length % 3 !== 0) {
        ui.push({ title: "　", url: "", style: { layout_flexBasisPercent: 0.00001 }});
    }
}

// ③ 分类模块 (三列排版+大标题，单独补全)
ui.push({ 
    title: isFlExpanded ? "▼ 📚 分类 (点击收起)" : "▶ 📚 分类 (点击展开)", 
    url: "", type: "button", 
    action: "(function(){var c={};try{c=JSON.parse(source.getVariable())}catch(e){};c.flExpanded=(c.flExpanded===false?true:false);source.setVariable(JSON.stringify(c));})();java.refreshExplore()", 
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 } 
});
if (isFlExpanded) {
    var tempCount = 0; // 单独给小分类计数
    flArr.forEach(function(item) {
        if (item.isHeader) {
            // 遇到大标题，如果上一排小按钮没满，先补位
            if (tempCount > 0 && tempCount % 3 !== 0) {
                ui.push({ title: "　", url: "", style: { layout_flexBasisPercent: 0.1} });
            }
            tempCount = 0; 
            // 推入大标题
            ui.push({ title: item.title, url: "", style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 } });
        } else {
            tempCount++;
            // 推入小分类
            ui.push({ title: item.title, url: item.url, style: { layout_flexBasisPercent: 0.3 } });
        }
    });
    // 收尾补位
    if (tempCount > 0 && tempCount % 3 !== 1) {
        ui.push({ title: "　", url: "", style: { layout_flexBasisPercent: 0.00001} });
    }
}

// 输出
JSON.stringify(ui);

