//JSON安全解析
function ImJson(input) {
    if (input && typeof input === "object") return input;
    return JSON.parse(String(input || "{}"));
}

//Legado ajax请求参数拼接工具（对齐lmRequest标准模板）
function ImRequest(url, options) {
    return String(url) + "," + JSON.stringify(options || {});
}

// 1. 字节数组 -> Hex
function bytesToHex(bytes) {
    if (!bytes) return "";
    try {
        var sb = new java.lang.StringBuilder();
        for(var i = 0; i < bytes.length; i++){
            var b = bytes[i] & 0xff;
            var hexStr = java.lang.Integer.toHexString(b);
            if(hexStr.length === 1){
                sb.append("0");
            }
            sb.append(hexStr);
        }
        return sb.toString();
    } catch(e) { return ""; }
}

// 2. Hex -> 字节数组
function hexToBytes(hex) {
    if (!hex || hex.length % 2 !== 0) return null;
    try {
        var len = hex.length;
        var bytes = new Array(len / 2);
        for (var i = 0; i < len; i += 2) {
            bytes[i / 2] = parseInt(hex.substring(i, i + 2), 16);
        }
        return bytes;
    } catch(e) { return null; }
}

// 3. 字节数组 -> 普通字符串 (UTF-8)
function bytesToString(bytes) {
    if (!bytes) return "";
    try {
        return new java.lang.String(bytes, "UTF-8");
    } catch(e) { return ""; }
}

// 4. 字节数组 -> Base64
function encodeBase64(bytes) {
    if (!bytes) return "";
    try {
        if (typeof android !== 'undefined' && android.util && android.util.Base64) {
            return android.util.Base64.encodeToString(bytes, 0).replace(/\n/g, "");
        }
        if (typeof java !== 'undefined' && java.util && java.util.Base64) {
            return java.util.Base64.getEncoder().encodeToString(bytes);
        }
    } catch(e) {}
    return bytesToHex(bytes);
}

// 5. 字符串 Base64 解码 (直接传 Base64 字符串，返回明文)
function decodeB64(str) {
    if (!str) return "";
    try {
        var b64 = str.replace(/-/g, '+').replace(/_/g, '/');
        while (b64.length % 4 !== 0) { b64 += '='; }
        var byteArr = java.base64DecodeToByteArray(b64);
        return bytesToString(byteArr);
    } catch(e) {
        return "";
    }
}

// 6. JWT 密文 -> 明文 JSON 对象
function parseJwt(jwtStr) {
    if (!jwtStr) return null;
    var parts = jwtStr.split('.');
    if (parts.length === 3) {
        var plainText = decodeB64(parts[1]);
        if (plainText) {
            try {
                return JSON.parse(plainText);
            } catch(e) {}
        }
    }
    return null;
}

// Base64解码
// 纯 JS 原生 Base64 解码（不依赖 Java，完美支持中文）
function base64Decode(s) {
    const base64Table = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    s = String(s).replace(/=+$/, '');
    let out = '';
    let bits = 0;
    let value = 0;
    for (let i = 0; i < s.length; i++) {
        let idx = base64Table.indexOf(s[i]);
        if (idx === -1) continue;
        value = (value << 6) | idx;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            // 先把字节推入数组
            out += '%' + ('00' + ((value >> bits) & 0xFF).toString(16)).slice(-2);
        }
    }
    try {
        // 用 decodeURIComponent 把十六进制转回正常中文
        return decodeURIComponent(out);
    } catch (e) {
        return out; // 如果解析失败，回退原始结果
    }
}

// 纯 JS 原生 Base64 加密（不依赖 Java，完美支持中文）
function base64Encode(str) {
    if (!str) return "";

    // 1. 先转 UTF-8 格式（防止中文乱码）
    var utf8Str = encodeURIComponent(String(str)).replace(/%([0-9A-F]{2})/g, function(match, p1) {
        return String.fromCharCode('0x' + p1);
    });

    const base64Table = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    let out = '';
    let i = 0;

    // 2. 核心算法：按 6 位分组转字符
    while (i < utf8Str.length) {
        let chr1 = utf8Str.charCodeAt(i++);
        let chr2 = utf8Str.charCodeAt(i++);
        let chr3 = utf8Str.charCodeAt(i++);

        let enc1 = chr1 >> 2;
        let enc2 = ((chr1 & 3) << 4) | (chr2 >> 4);
        let enc3 = ((chr2 & 15) << 2) | (chr3 >> 6);
        let enc4 = chr3 & 63;

        // 处理剩余字符（不足3个字节）
        if (isNaN(chr2)) {
            enc3 = enc4 = 64;
        } else if (isNaN(chr3)) {
            enc4 = 64;
        }

        out += base64Table.charAt(enc1) + base64Table.charAt(enc2) +
               (enc3 === 64 ? '=' : base64Table.charAt(enc3)) +
               (enc4 === 64 ? '=' : base64Table.charAt(enc4));
    }

    return out;
}

ruleToc.chapterList:
@js:
var list = [];
var base = String(baseUrl);
var html = java.ajax(base);
var doc = org.jsoup.Jsoup.parse(html);
var lis = doc.select("ul#bookIndexList > li");
var domain = "https://book.washai.net";
var href;
for (var i = 0; i < lis.size(); i++) {
    var li = lis.get(i);
    if (li.hasClass("catalogVolumeHeading") || li.select("h4").size() > 0) {
        var t = String(li.select("h4").text()).trim();
        var name = t || "正文";
        list.push({
            text: "🏮〖" + name + "〗🏮",
            href: href,
            volume: true
        });
    } 
    // 2. 识别章节
    else {
        var a = li.select("a").first();
        if (!a) continue;
        var rawText = String(a.text()).trim();
        href = String(a.attr("href") || "");
        if (!rawText || !href) continue;
        if (href.indexOf("http") !== 0 && href.indexOf("//") !== 0) {
            href = domain + (href.charAt(0) === "/" ? href : "/" + href);
        }

        var symbol = rawText.indexOf("免费") !== -1 ? "📝 " : "🔒 ";
        var cleanName = rawText.replace(/\[免费\]/g, "")
                               .replace(/\[VIP\]/gi, "")
                               .replace(/免费/g, "")
                               .replace(/VIP/gi, "")
                               .trim();

        // 推入章节
        list.push({ text: symbol + cleanName, href: href });
    }
}
list;

